#!/usr/bin/env python3
"""Spec ID generator: deterministic JAH-SPEC-###### IDs."""
import re

PATTERN = re.compile(r"^JAH-SPEC-\d{6}$")

class SpecCounter:
    def __init__(self, start=1):
        self.next = start
        self.issued = set()
    def mint(self):
        sid = "JAH-SPEC-%06d" % self.next
        assert PATTERN.match(sid) and sid not in self.issued
        self.issued.add(sid)
        self.next += 1
        return sid
    @staticmethod
    def valid(sid):
        return bool(PATTERN.match(sid))

if __name__ == "__main__":
    c = SpecCounter(438347)
    ids = [c.mint() for _ in range(3)]
    print(ids)
    assert ids == ["JAH-SPEC-438347", "JAH-SPEC-438348", "JAH-SPEC-438349"]
    assert SpecCounter.valid("JAH-SPEC-000001") and not SpecCounter.valid("JAH-SPEC-42")
    assert not SpecCounter.valid("JAH-SPEC-000001 ")
    print("OK: deterministic IDs minted in order, validation correct")

#!/usr/bin/env python3
"""Lineage chain builder: parent/child links with root-walking."""
class Lineage:
    def __init__(self):
        self.parent = {}
        self.relation = {}
    def link(self, child, parent, relation):
        assert child not in self.parent, "child already has a parent"
        self.parent[child] = parent
        self.relation[child] = relation
    def walk(self, node):
        chain = [node]
        while node in self.parent:
            node = self.parent[node]
            chain.append(node)
        return chain

if __name__ == "__main__":
    lg = Lineage()
    lg.link("JAH-MIX-0002", "JAH-PROG-0001", "mix-of")
    lg.link("JAH-MIX-0002b", "JAH-MIX-0002", "version-of")
    lg.link("JAH-PROG-0001", "JAH-SPEC-000010", "derived-from")
    chain = lg.walk("JAH-MIX-0002b")
    print("lineage:", " -> ".join(chain))
    assert chain == ["JAH-MIX-0002b", "JAH-MIX-0002", "JAH-PROG-0001", "JAH-SPEC-000010"]
    print("OK: lineage walks to the root")

#!/usr/bin/env python3
"""Hash ID coder: short deterministic IDs from any string."""
import hashlib

def hid(text, length=8):
    return hashlib.sha256(text.encode()).hexdigest()[:length].upper()

if __name__ == "__main__":
    items = ["Self-watering planter", "Sorting visualizer", "Maker-mark stamper"]
    ids = [hid(t) for t in items]
    for t, i in zip(items, ids):
        print("%-22s -> JAH-H-%s" % (t, i))
    assert len(set(ids)) == 3, "collision in demo set"
    assert hid("abc") == hid("abc"), "must be deterministic"
    assert all(len(i) == 8 for i in ids)
    print("OK: deterministic, unique-in-demo, fixed-length IDs")

#!/usr/bin/env python3
"""Record validator: schema-check database records."""
import re

SCHEMA = {"id": r"^JAH-[A-Z]+-\d+$", "title": str, "description": str,
          "ladder_rank": (1, 2, 3)}

def validate(rec):
    errors = []
    if not re.match(SCHEMA["id"], rec.get("id", "")):
        errors.append("bad id")
    for f in ("title", "description"):
        if not isinstance(rec.get(f), str) or not rec[f].strip():
            errors.append("bad " + f)
    if rec.get("ladder_rank") not in (1, 2, 3):
        errors.append("bad ladder_rank")
    return errors

if __name__ == "__main__":
    good = {"id": "JAH-REC-000001", "title": "T", "description": "D", "ladder_rank": 2}
    bad = {"id": "nope", "title": "", "ladder_rank": 9}
    assert validate(good) == []
    errs = validate(bad)
    print("bad record errors:", errs)
    assert len(errs) == 4
    print("OK: good record passes, bad record fails with 4 errors")

#!/usr/bin/env python3
"""Text banner maker: 5x5 block-font ASCII banners."""
FONT = {
 "A": [" ### ", "#   #", "#####", "#   #", "#   #"],
 "H": ["#   #", "#   #", "#####", "#   #", "#   #"],
 "J": ["  ###", "   # ", "   # ", "#  # ", " ##  "],
 " ": ["     ", "     ", "     ", "     ", "     "],
}

def banner(text):
    text = text.upper()
    rows = [""] * 5
    for ch in text:
        glyph = FONT.get(ch, FONT[" "])
        for i in range(5):
            rows[i] += glyph[i] + " "
    return "\n".join(rows)

if __name__ == "__main__":
    out = banner("JAH")
    print(out)
    assert out.count("#") > 20
    assert len(out.split("\n")) == 5
    print("OK: 5-row banner rendered")

#!/usr/bin/env python3
"""Word scrambler: typoglycemia demo (seeded)."""
import random, re

def scramble_word(w, rng):
    if len(w) <= 3:
        return w
    mid = list(w[1:-1])
    rng.shuffle(mid)
    return w[0] + "".join(mid) + w[-1]

def scramble(text, seed=5):
    rng = random.Random(seed)
    return re.sub(r"[A-Za-z]+", lambda m: scramble_word(m.group(0), rng), text)

if __name__ == "__main__":
    text = "The archive grows every single day"
    out = scramble(text)
    print("in: ", text)
    print("out:", out)
    assert out.split()[0] == "The"
    for a, b in zip(text.split(), out.split()):
        assert a[0] == b[0] and a[-1] == b[-1] and sorted(a) == sorted(b)
    print("OK: interiors scrambled, first/last letters kept")

#!/usr/bin/env python3
"""Number to words: 0..999999 in English."""
ONES = ["zero","one","two","three","four","five","six","seven","eight","nine","ten",
        "eleven","twelve","thirteen","fourteen","fifteen","sixteen","seventeen",
        "eighteen","nineteen"]
TENS = ["","","twenty","thirty","forty","fifty","sixty","seventy","eighty","ninety"]

def num_to_words(n):
    assert 0 <= n <= 999999
    if n < 20:
        return ONES[n]
    if n < 100:
        return TENS[n//10] + ("" if n % 10 == 0 else "-" + ONES[n%10])
    if n < 1000:
        return ONES[n//100] + " hundred" + ("" if n % 100 == 0 else " " + num_to_words(n%100))
    return num_to_words(n//1000) + " thousand" + ("" if n % 1000 == 0 else " " + num_to_words(n%1000))

if __name__ == "__main__":
    for n, want in [(0,"zero"),(42,"forty-two"),(100,"one hundred"),(2026,"two thousand twenty-six"),
                    (100000,"one hundred thousand")]:
        got = num_to_words(n)
        print(n, "->", got)
        assert got == want
    print("OK: 5 conversions correct")

#!/usr/bin/env python3
"""Roman numerals: both directions."""
VALS = [(1000,"M"),(900,"CM"),(500,"D"),(400,"CD"),(100,"C"),(90,"XC"),
        (50,"L"),(40,"XL"),(10,"X"),(9,"IX"),(5,"V"),(4,"IV"),(1,"I")]

def to_roman(n):
    out = ""
    for v, s in VALS:
        while n >= v:
            out += s; n -= v
    return out

def from_roman(s):
    total, i = 0, 0
    mp = {sym: v for v, sym in VALS}
    while i < len(s):
        if i+1 < len(s) and mp[s[i:i+2]] if s[i:i+2] in mp else False:
            total += mp[s[i:i+2]]; i += 2
        else:
            total += mp[s[i]]; i += 1
    return total

if __name__ == "__main__":
    for n, want in [(2026,"MMXXVI"),(4,"IV"),(9,"IX"),(1999,"MCMXCIX"),(42,"XLII")]:
        assert to_roman(n) == want, n
        assert from_roman(want) == n, want
        print(n, "<->", want)
    print("OK: roman numerals round-trip both ways")

#!/usr/bin/env python3
"""Grade calculator: weighted grades -> letter."""
def letter(pct):
    for cut, g in ((90,"A"),(80,"B"),(70,"C"),(60,"D")):
        if pct >= cut:
            return g
    return "F"

def course_grade(cats):
    # cats: [(weight, score), ...]; weights sum to 1
    total_w = sum(w for w, s in cats)
    assert abs(total_w - 1.0) < 1e-9, "weights must sum to 1"
    return sum(w*s for w, s in cats)

if __name__ == "__main__":
    g = course_grade([(0.4, 92), (0.3, 85), (0.2, 78), (0.1, 95)])
    print("weighted score: %.1f -> %s" % (g, letter(g)))
    assert abs(g - 87.4) < 1e-9 and letter(g) == "B"
    assert letter(91) == "A" and letter(59.9) == "F"
    print("OK: weighted grade and letter boundaries correct")

