"""Countdown timer: ticks down, demo uses instant ticks."""
import time

def countdown(n, tick=0):
    out = []
    for i in range(n, 0, -1):
        out.append(i)
        print(i)
        if tick:
            time.sleep(tick)
    print("LIFTOFF")
    return out

if __name__ == "__main__":
    seq = countdown(5)
    assert seq == [5, 4, 3, 2, 1]
    print("OK: countdown sequence correct")

#!/usr/bin/env python3
"""Hangman: scripted demo of win and lose paths."""
def play(word, guesses, lives=6):
    found = ["_"] * len(word)
    used = []
    for g in guesses:
        if g in used:
            continue
        used.append(g)
        if g in word:
            for i, ch in enumerate(word):
                if ch == g:
                    found[i] = g
        else:
            lives -= 1
        if "_" not in found:
            return True, "".join(found), lives
        if lives == 0:
            return False, "".join(found), 0
    return "_" not in found, "".join(found), lives

if __name__ == "__main__":
    won, state, lives = play("archive", ["a", "e", "r", "c", "h", "i", "v"])
    print("win path:", won, state, "lives left:", lives)
    assert won and state == "archive"
    lost, state2, lives2 = play("quiz", ["a", "b", "c", "d", "e", "f", "g"])
    print("lose path:", lost, state2, "lives left:", lives2)
    assert not lost and lives2 == 0
    print("OK: hangman win and lose paths verified")

#!/usr/bin/env python3
"""Rock-paper-scissors: scripted tournament vs seeded computer."""
import random

BEATS = {"rock": "scissors", "scissors": "paper", "paper": "rock"}

def round_result(player, computer):
    if player == computer:
        return "tie"
    return "win" if BEATS[player] == computer else "lose"

if __name__ == "__main__":
    rng = random.Random(11)
    moves = ["rock", "paper", "scissors"]
    player_seq = ["rock", "rock", "paper", "scissors", "paper", "rock"]
    score = {"win": 0, "lose": 0, "tie": 0}
    for pm in player_seq:
        cm = rng.choice(moves)
        r = round_result(pm, cm)
        score[r] += 1
        print("you=%-8s cpu=%-8s -> %s" % (pm, cm, r))
    assert sum(score.values()) == len(player_seq)
    # rule check on all 9 combos
    for p in moves:
        for c in moves:
            r = round_result(p, c)
            assert (r == "tie") == (p == c)
    print("final:", score)
    print("OK: all 9 matchups follow the rules")

#!/usr/bin/env python3
"""Acronym maker: phrase -> acronym, two styles."""
SKIP = {"of", "the", "and", "a", "an", "to", "for"}

def acronym(phrase, dotted=False):
    words = [w for w in phrase.split() if w.lower() not in SKIP]
    letters = [w[0].upper() for w in words]
    return (".".join(letters) + ".") if dotted else "".join(letters)

if __name__ == "__main__":
    cases = [("Signature Universal Paradox Immune Calculator", "SUPIC"),
             ("JAH Databases", "JD"),
             ("All Database Merger", "ADM")]
    for phrase, want in cases:
        got = acronym(phrase)
        print(phrase, "->", got)
        assert got == want
    assert acronym("JAH Databases", dotted=True) == "J.D."
    print("OK: acronyms correct in both styles")
